// Evaluation logic for road hazard freshness & reconfirmation window
const now = new Date();
const items = $input.all();

// Thresholds in hours:
// Waterlogged roads change dynamically after rain: 24h
// Potholes and road cracks: 168h (7 days)
const results = [];

for (const item of items) {
  const hazard = item.json;
  const lastConfirmedTime = new Date(hazard.lastConfirmedAt || hazard.lastUpdatedAt || hazard.firstReportedAt);
  const ageHours = (now.getTime() - lastConfirmedTime.getTime()) / (1000 * 60 * 60);

  const isWaterlog = hazard.category === 'waterlogged_road' || hazard.category === 'waterlogging';
  const maxHours = isWaterlog ? 24 : 168;

  const isStale = ageHours > maxHours && hazard.status !== 'CONFIRMED_RESOLVED';

  results.push({
    json: {
      hazardId: hazard.id,
      title: hazard.title,
      category: hazard.category,
      locality: hazard.locality,
      ageHours: Math.round(ageHours),
      revalidationWindowHours: maxHours,
      isStale,
      newStatus: isStale ? 'STALE_NEEDS_RECONFIRMATION' : hazard.status,
      staleReason: isStale ? `No confirmation received in past ${Math.round(ageHours)}h` : null,
      evaluatedAt: now.toISOString()
    }
  });
}

return results;

// Summarize stale hazards for municipal maintenance audit
const staleItems = $input.all().map(i => i.json);

return {
  json: {
    workflowName: 'RoadSense — Hazard Freshness and Reconfirmation',
    staleHazardsIdentified: staleItems.length,
    hazards: staleItems,
    action: 'FLAGGED_STALE_NEEDS_RECONFIRMATION',
    executedAt: new Date().toISOString()
  }
};
